                let area = w * w;
                if area > largest_figure {
                    largest_figure = area;
                }
            }
            (w, h) if *w == 0 => {
                let area = 3 * (*h as f64).powi(2) as i64;
                if area > largest_figure {
                    largest_figure = area;
                }
            }
            (w, h) => {
                let area = w * h;
                if area > largest_figure {
                    largest_figure = area;
                }
            }
        }
